SELECT CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(ss.revenue) AS revenue_count, ROUND(STDDEV(ss.units), 2) AS stddev_units FROM store_sales ss JOIN products p ON ss.product_id = p.id JOIN suppliers s ON p.supplier_id = s.id WHERE s.country = 'DE' GROUP BY CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 1.6 THEN 'mid' ELSE 'low' END HAVING COUNT(ss.revenue) >= 3
